import re


_PATTERN = re.compile(r"^(\d+h)?(\d+m)?(\d+s)?$", re.IGNORECASE)


def parse_duration(text):
    """Parse a duration like '1h30m' into whole seconds, raising ValueError on bad input."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")
    match = _PATTERN.match(text)
    if match is None:
        raise ValueError(f"invalid duration: {text!r}")
    total = 0
    for group, multiplier in zip(match.groups(), (3600, 60, 1)):
        if group:
            total += int(group[:-1]) * multiplier
    if total == 0 and text.strip("") == "":
        raise ValueError(f"invalid duration: {text!r}")
    return total


