#!/usr/bin/env python3
"""Total durations read one per line from stdin.

Skips blank lines. On an invalid line, prints an error to stderr and
exits with status 1. Otherwise prints the total via format_duration.
"""

import sys

from durations import format_duration, parse_duration


def main() -> int:
    total = 0
    for number, line in enumerate(sys.stdin, start=1):
        line = line.strip()
        if not line:
            continue
        try:
            total += parse_duration(line)
        except ValueError:
            print(f"invalid duration on line {number}: {line!r}", file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Parse duration strings like '1h30m', '1 hour 30 minutes' or '45s' into
whole seconds.

Also provides format_duration(seconds), the inverse: it turns whole
seconds back into the shortest string parse_duration accepts.
"""

import re

_UNIT_FACTORS = {"d": 86400, "h": 3600, "m": 60, "s": 1}

_LONG_NAMES = {
    "day": "d", "days": "d",
    "hour": "h", "hours": "h",
    "minute": "m", "minutes": "m",
    "second": "s", "seconds": "s",
}

_TOKEN_RE = re.compile(
    r"(\d+(?:\.\d+)?)\s*(dhms|days?|hours?|minutes?|seconds?)"
)

_STRIP_NUMBERS_RE = re.compile(r"\d+(?:\.\d+)?")


def parse_duration(text):
    """Return the number of seconds represented by *text*.

    Accepts combinations of days, hours, minutes and seconds, with unit
    letters ('1h30m', '45s', '1d1h1m1s') or full words ('1 hour 30
    minutes'). Anything else raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    tokens = _TOKEN_RE.findall(text)
    if not tokens:
        raise ValueError("invalid duration: %r" % (text,))
    # The leftover text with numbers stripped must consist only of unit
    # names and whitespace, otherwise something unrecognized was skipped.
    rest = _STRIP_NUMBERS_RE.sub("", text)
    for unit in re.findall(r"[a-zA-Z]+", rest):
        if unit.lower() not in _LONG_NAMES:
            raise ValueError("invalid duration: %r" % (text,))
    seen = set()
    total = 0
    for value, unit in tokens:
        letter = unit[0].lower()
        if letter in seen:
            raise ValueError("repeated unit in duration: %r" % (text,))
        seen.add(letter)
        if unit not in _UNIT_FACTORS:
            unit = _LONG_NAMES[unit.lower()]
        total += float(value) * _UNIT_FACTORS[unit]
    if total != int(total):
        raise ValueError("duration must resolve to whole seconds: %r" % (text,))
    return int(total)


def format_duration(seconds):
    """Return the shortest duration string parse_duration accepts.

    For example 5400 -> '1h30m' and 90061 -> '1d1h1m1s'.
    """
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("seconds must be a whole number")
    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    if seconds == 0:
        return "0s"
    parts = []
    remaining = seconds
    for unit, factor in (("d", 86400), ("h", 3600), ("m", 60), ("s", 1)):
        count, remaining = divmod(remaining, factor)
        if count:
            parts.append(f"{count}{unit}")
    return "".join(parts)


def _selftest():
    cases = [
        (0, "0s"),
        (45, "45s"),
        (3600, "1h"),
        (5400, "1h30m"),
        (5402, "1h30m2s"),
        (90061, "1d1h1m1s"),
        (86400, "1d"),
    ]
    for value, expected in cases:
        result = format_duration(value)
        assert result == expected, (value, result, expected)
        assert parse_duration(result) == value, (value, result)

    parse_cases = [
        ("1h30m", 5400),
        ("45s", 45),
        ("1.5h", 5400),
        ("1d", 86400),
        ("2d5h", 190800),
        ("1 hour 30 minutes", 5400),
        ("1 hour", 3600),
        ("45 seconds", 45),
        ("1 day 2 hours", 93600),
    ]
    for text, expected in parse_cases:
        result = parse_duration(text)
        assert result == expected, (text, result, expected)

    bad_cases = ["soon", "2 hours 3", "1h30x", 42, None]
    for text in bad_cases:
        try:
            parse_duration(text)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError: %r" % (text,))


if __name__ == "__main__":
    _selftest()
    print("selftest OK")

